// ==== END ON-BOARD MODEL ====

// ---- On-board gesture recognition (TinyML) ----
// The same 96 features as gesture/gesture_features.py, then a vote over the decision trees in MODEL.
// MODEL layout: one UInt16 root node index per tree, then 7 bytes per node:
//   feature index (255 = leaf), Float32 threshold, UInt16 right child (or class index for a leaf).
// The left child of a node always comes straight after it.
const RESAMPLE_POINTS = 16
const MIN_SAMPLES = 6
const NODE_BYTES = 7
let recX: number[] = []
let recY: number[] = []
let recZ: number[] = []

// Mean, std, min, max, range and the time position (0-1) of the min and max
function addAxisStats(a: number[], f: number[]) {
    const n = a.length
    let sum = 0
    let lo = 0
    let hi = 0
    for (let i = 0; i < n; i++) {
        sum += a[i]
        if (a[i] < a[lo]) lo = i
        if (a[i] > a[hi]) hi = i
    }
    const mean = sum / n
    let squares = 0
    for (let i = 0; i < n; i++) {
        squares += (a[i] - mean) * (a[i] - mean)
    }
    f.push(mean)
    f.push(Math.sqrt(squares / n))
    f.push(a[lo])
    f.push(a[hi])
    f.push(a[hi] - a[lo])
    f.push(lo / (n - 1))
    f.push(hi / (n - 1))
}

function signOf(v: number): number {
    if (v > 0) return 1
    if (v < 0) return -1
    return 0
}

// How often the signal crosses its own mean, per sample
function zeroCrossingRate(a: number[]): number {
    const n = a.length
    let sum = 0
    for (let i = 0; i < n; i++) sum += a[i]
    const mean = sum / n
    let crossings = 0
    let previous = signOf(a[0] - mean)
    for (let i = 1; i < n; i++) {
        const s = signOf(a[i] - mean)
        if (s != previous) crossings++
        previous = s
    }
    return crossings / (n - 1)
}

// The signal stretched or squeezed to RESAMPLE_POINTS evenly spaced points (its shape)
function addResampled(a: number[], f: number[]) {
    const n = a.length
    for (let k = 0; k < RESAMPLE_POINTS; k++) {
        const t = k * (n - 1) / (RESAMPLE_POINTS - 1)
        const i = Math.floor(t)
        if (i >= n - 1) {
            f.push(a[n - 1])
        } else {
            f.push(a[i] + (a[i + 1] - a[i]) * (t - i))
        }
    }
}

function gestureFeatures(): number[] {
    const n = recX.length
    const mag: number[] = []
    for (let i = 0; i < n; i++) {
        mag.push(Math.sqrt(recX[i] * recX[i] + recY[i] * recY[i] + recZ[i] * recZ[i]))
    }
    const signals = [recX, recY, recZ, mag]
    const f: number[] = [n]
    for (let s = 0; s < 4; s++) addAxisStats(signals[s], f)
    for (let s = 0; s < 3; s++) f.push(zeroCrossingRate(signals[s]))
    for (let s = 0; s < 4; s++) addResampled(signals[s], f)
    return f
}

// Each tree votes for one gesture; the gesture with the most votes wins
function predictOnBoard() {
    const f = gestureFeatures()
    const votes: number[] = []
    for (let c = 0; c < MODEL_CLASSES.length; c++) votes.push(0)
    const nodesStart = 2 * MODEL_TREES
    for (let tree = 0; tree < MODEL_TREES; tree++) {
        let node = MODEL.getNumber(NumberFormat.UInt16LE, 2 * tree)
        let at = nodesStart + node * NODE_BYTES
        while (MODEL[at] != 255) {
            if (f[MODEL[at]] <= MODEL.getNumber(NumberFormat.Float32LE, at + 1)) {
                node = node + 1
            } else {
                node = MODEL.getNumber(NumberFormat.UInt16LE, at + 5)
            }
            at = nodesStart + node * NODE_BYTES
        }
        votes[MODEL.getNumber(NumberFormat.UInt16LE, at + 5)] += 1
    }
    let best = 0
    for (let c = 1; c < votes.length; c++) {
        if (votes[c] > votes[best]) best = c
    }
    const confidence = votes[best] / MODEL_TREES
    // Tell the laptop what the board decided (index into MODEL_CLASSES, confidence in %)
    serial.writeLine("PRED:" + best + "," + Math.round(confidence * 100))
    if (confidence >= MODEL_THRESHOLD) {
        display(MODEL_CLASSES[best])
    } else {
        display("?")
    }
}

// Main sampling loop (pause 20 ms; ~20-25 readings per second in practice)
basic.forever(function () {
    if (input.buttonIsPressed(Button.A)) {
        if (!recording) {
            recording = true
            recX = []
            recY = []
            recZ = []
            basic.clearScreen()
            led.plot(2, 2)
            serial.writeLine("START")
        }
    } else if (recording) {
        recording = false
        led.unplot(2, 2)
        // Recognise the gesture on the micro:bit itself. PRED is sent before END,
        // so the laptop knows the board has its own model and leaves the LEDs to it.
        if (MODEL_TREES > 0 && recX.length >= MIN_SAMPLES) {
            predictOnBoard()
        }
        serial.writeLine("END")
    }

    const x = input.acceleration(Dimension.X)
    const y = input.acceleration(Dimension.Y)
    const z = input.acceleration(Dimension.Z)
    if (recording) {
        recX.push(x)
        recY.push(y)
        recZ.push(z)
    }

    // Sends comma-separated values: "x,y,z"
    serial.writeLine("" + x + "," + y + "," + z)

    // 20 ms pause between readings
    basic.pause(20)
})
